<script setup lang="ts">
import { ref } from 'vue';
import { router } from '@inertiajs/vue3';

type RequestItem = {
    id: number;
    email: string;
    method: 'email' | 'google';
    status: string;
    created_at: string;
    user: { id: number; name: string; email: string; google_id: string | null; deleted_at: string | null } | null;
    approver: { id: number; name: string; role: string } | null;
};
const props = defineProps<{ requests: { data: RequestItem[]; total: number; current_page: number; last_page: number }; summary: { pending: number; approved: number; rejected: number; restored: number } }>();
const selected = ref<RequestItem | null>(null);
const rejecting = ref<RequestItem | null>(null);
const reviewNote = ref('');
function approve(item: RequestItem) { if (!confirm(`Khôi phục tài khoản ${item.user?.name ?? item.email}?`)) return; router.patch(`/admin/account-recovery-requests/${item.id}/approve`); }
function openReject(item: RequestItem) { rejecting.value = item; reviewNote.value = ''; }
function reject() { if (!rejecting.value || !reviewNote.value.trim()) return; router.patch(`/admin/account-recovery-requests/${rejecting.value.id}/reject`, { review_note: reviewNote.value }, { onSuccess: () => { rejecting.value = null; reviewNote.value = ''; } }); }
function methodLabel(method: string) { return method === 'google' ? 'Google' : 'Email + OTP'; }
function statusLabel(status: string) { return status === 'pending_approval' ? 'Chờ phê duyệt' : status === 'restored' ? 'Đã khôi phục' : status === 'rejected' ? 'Đã từ chối' : status; }
</script>
<template>
<div class="admin-page">
    <div class="request-head"><div><div class="admin-kicker">HỆ THỐNG</div><h1>Khôi phục tài khoản</h1><p>Quản lý yêu cầu khôi phục tài khoản đã được xóa mềm. Quản trị viên hoặc nhân viên cấp cao chỉ cần một người phê duyệt.</p></div><div class="request-count"><i class="bi bi-person-check"/><div><strong>{{ props.summary.pending }}</strong><small>chờ phê duyệt</small></div></div></div>
    <div class="request-stats row g-3 mb-4"><div class="col-12 col-md-3"><div class="request-stat pending"><small>Chờ phê duyệt</small><strong>{{ props.summary.pending }}</strong></div></div><div class="col-12 col-md-3"><div class="request-stat approved"><small>Đã khôi phục</small><strong>{{ props.summary.restored }}</strong></div></div><div class="col-12 col-md-3"><div class="request-stat rejected"><small>Đã từ chối</small><strong>{{ props.summary.rejected }}</strong></div></div><div class="col-12 col-md-3"><div class="request-stat"><small>Tổng yêu cầu</small><strong>{{ props.requests.total }}</strong></div></div></div>
    <div class="admin-panel overflow-hidden"><div class="table-responsive"><table class="table admin-table align-middle"><thead><tr><th>Khách hàng</th><th>Phương thức</th><th>Ngày yêu cầu</th><th>Trạng thái</th><th class="text-end">Xử lý</th></tr></thead><tbody><tr v-for="item in props.requests.data" :key="item.id"><td><div class="request-user"><span class="request-avatar"><i class="bi bi-person-fill"/></span><div><strong>{{ item.user?.name ?? 'Tài khoản không còn tồn tại' }}</strong><small>{{ item.user?.email ?? item.email }}</small></div></div></td><td><span class="method"><i :class="item.method === 'google' ? 'bi bi-google' : 'bi bi-envelope'"/> {{ methodLabel(item.method) }}</span></td><td>{{ new Date(item.created_at).toLocaleString('vi-VN') }}</td><td><span :class="['request-status', item.status]"><i class="bi bi-dot"/>{{ statusLabel(item.status) }}</span></td><td class="text-end"><div v-if="item.status === 'pending_approval'" class="request-actions"><button class="request-action approve" title="Phê duyệt" @click="approve(item)"><i class="bi bi-check-lg"/></button><button class="request-action reject" title="Từ chối" @click="openReject(item)"><i class="bi bi-x-lg"/></button></div><span v-else class="processed-mark">{{ item.approver ? `Đã duyệt bởi ${item.approver.name}` : 'Đã xử lý' }}</span></td></tr><tr v-if="!props.requests.data.length"><td colspan="5" class="empty-state"><i class="bi bi-inbox"/><strong>Chưa có yêu cầu khôi phục</strong><span>Yêu cầu từ khách hàng sẽ xuất hiện tại đây.</span></td></tr></tbody></table></div></div>
    <div v-if="rejecting" class="modal d-block admin-modal-backdrop"><div class="modal-dialog modal-dialog-centered"><div class="modal-content border-0 shadow-lg request-modal"><div class="modal-header"><div><div class="modal-kicker">YÊU CẦU #{{ rejecting.id }}</div><h5 class="mb-0">Từ chối khôi phục</h5></div><button class="btn-close" @click="rejecting=null"/></div><div class="modal-body"><div class="detail-user"><span class="detail-avatar"><i class="bi bi-person-fill"/></span><div><strong>{{ rejecting.user?.name ?? 'Tài khoản không còn tồn tại' }}</strong><small>{{ rejecting.email }}</small></div></div><div class="field"><label class="form-label">Lý do từ chối</label><textarea v-model="reviewNote" class="form-control" rows="4" placeholder="Nhập lý do..."/></div></div><div class="modal-footer"><button class="btn btn-light" @click="rejecting=null">Hủy</button><button class="btn btn-danger" :disabled="!reviewNote.trim()" @click="reject">Xác nhận từ chối</button></div></div></div></div>
</div>
</template>
